const pipeline = (x) => x();

const importers = [
  async (path) => {
    if (!/^\.[\\/](?:\.storybook\/(?!\.)(?=.)[^/]*?\.mdx)$/.exec(path)) {
      return;
    }
  
    const pathRemainder = path.substring(13);
    return import(
      /* webpackChunkName: "[request]" */
      /* webpackInclude: /(?!.*node_modules)(?:\/\.storybook\/(?!\.)(?=.)[^/]*?\.mdx)$/ */
      './.storybook/' + pathRemainder
    );
  }
  ,
  async (path) => {
    if (!/^\.[\\/](?:packages(?:\/(?!\.)(?:(?:(?!(?:^|\/)\.).)*?)\/|\/|$)demo\/(?!\.)(?=.)[^/]*?\.stories\.js)$/.exec(path)) {
      return;
    }
  
    const pathRemainder = path.substring(11);
    return import(
      /* webpackChunkName: "[request]" */
      /* webpackInclude: /(?!.*node_modules)(?:\/packages(?:\/(?!\.)(?:(?:(?!(?:^|\/)\.).)*?)\/|\/|$)demo\/(?!\.)(?=.)[^/]*?\.stories\.js)$/ */
      './packages/' + pathRemainder
    );
  }
  
];

export async function importFn(path) {
  for (let i = 0; i < importers.length; i++) {
    const moduleExports = await pipeline(() => importers[i](path));
    if (moduleExports) {
      return moduleExports;
    }
  }
}